INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'el','Στον χώρο σας','Ο επαγγελματίας θα πρέπει να έρθει στον χώρο παροχής της υπηρεσίας.' FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='delivery_mode' AND o.option_value='ON_SITE';
INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'el','Ευέλικτο','Μπορεί να γίνει είτε εξ αποστάσεως είτε στον χώρο σας.' FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='delivery_mode' AND o.option_value='FLEXIBLE';
